71	lv_display_t * lv_nuttx_fbdev_create(void)
72	{
73	    lv_nuttx_fb_t * dsc = lv_malloc_zeroed(sizeof(lv_nuttx_fb_t));
74	    LV_ASSERT_MALLOC(dsc);
75	    if(dsc == NULL) return NULL;
76	
77	    lv_display_t * disp = lv_display_create(800, 480);
78	    if(disp == NULL) {
79	        lv_free(dsc);
80	        return NULL;
81	    }
82	    dsc->fd = -1;
83	    lv_display_set_driver_data(disp, dsc);
84	    lv_display_add_event_cb(disp, display_release_cb, LV_EVENT_DELETE, disp);
85	    lv_display_set_flush_cb(disp, flush_cb);
86	    return disp;
87	}
