89	int lv_nuttx_fbdev_set_file(lv_display_t * disp, const char * file)
90	{
91	    int ret;
92	    LV_ASSERT(disp && file);
93	    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);
94	
95	    if(dsc->fd >= 0) close(dsc->fd);
96	
97	    /* Open the file for reading and writing*/
98	
99	    dsc->fd = open(file, O_RDWR | O_CLOEXEC);
100	    if(dsc->fd < 0) {
101	        LV_LOG_ERROR("Error: cannot open framebuffer device");
102	        return -errno;
103	    }
104	    LV_LOG_USER("The framebuffer device was opened successfully");
105	
106	    if(ioctl(dsc->fd, FBIOGET_VIDEOINFO, (unsigned long)((uintptr_t)&dsc->vinfo)) < 0) {
107	        LV_LOG_ERROR("ioctl(FBIOGET_VIDEOINFO) failed: %d", errno);
108	        ret = -errno;
109	        goto errout;
110	    }
111	
112	    LV_LOG_USER("VideoInfo:");
113	    LV_LOG_USER("      fmt: %u", dsc->vinfo.fmt);
114	    LV_LOG_USER("     xres: %u", dsc->vinfo.xres);
115	    LV_LOG_USER("     yres: %u", dsc->vinfo.yres);
116	    LV_LOG_USER("  nplanes: %u", dsc->vinfo.nplanes);
117	
118	    if((ret = fbdev_get_pinfo(dsc->fd, &dsc->pinfo)) < 0) {
119	        goto errout;
120	    }
121	
122	    lv_color_format_t color_format = fb_fmt_to_color_format(dsc->vinfo.fmt);
123	    if(color_format == LV_COLOR_FORMAT_UNKNOWN) {
124	        goto errout;
125	    }
126	
127	    dsc->mem = mmap(NULL, dsc->pinfo.fblen, PROT_READ | PROT_WRITE,
128	                    MAP_SHARED | MAP_FILE, dsc->fd, 0);
129	    if(dsc->mem == MAP_FAILED) {
130	        LV_LOG_ERROR("ioctl(FBIOGET_PLANEINFO) failed: %d", errno);
131	        ret = -errno;
132	        goto errout;
133	    }
134	
135	    uint32_t w = dsc->vinfo.xres;
136	    uint32_t h = dsc->vinfo.yres;
137	    uint32_t stride = dsc->pinfo.stride;
138	    uint32_t data_size = h * stride;
139	
140	    LV_LOG_USER("=== LVGL FBDEV INIT ===");
141	    LV_LOG_USER("Resolution: %dx%d", w, h);
142	    LV_LOG_USER("BPP: %d", dsc->pinfo.bpp);
143	    LV_LOG_USER("Stride: %d bytes", stride);
144	    LV_LOG_USER("FBLen: %d bytes", dsc->pinfo.fblen);
145	    LV_LOG_USER("DataSize: %d bytes", data_size);
146	    LV_LOG_USER("FBMem: %p", dsc->mem);
147	    LV_LOG_USER("ColorFormat: %d", color_format);
148	
149	    /* Check alignment */
150	    uintptr_t mem_align = (uintptr_t)dsc->mem;
151	    uint32_t align = LV_DRAW_BUF_ALIGN;
152	    LV_LOG_USER("Alignment Check:");
153	    LV_LOG_USER("  LV_DRAW_BUF_ALIGN = %d", align);
154	    LV_LOG_USER("  mem address = %p", dsc->mem);
155	    LV_LOG_USER("  mem %% align = %d (should be 0)", mem_align % align);
156	    LV_LOG_USER("  stride = %d", stride);
157	    LV_LOG_USER("  stride %% align = %d (should be 0)", stride % align);
158	    LV_LOG_USER("  data_size = %d", data_size);
159	    LV_LOG_USER("  data_size %% align = %d (should be 0)", data_size % align);
160	
161	    if(mem_align % align != 0) {
162	        LV_LOG_ERROR("ERROR: Buffer address NOT aligned!");
163	    }
164	    if(stride % align != 0) {
165	        LV_LOG_ERROR("ERROR: Stride NOT aligned!");
166	    }
167	
168	    lv_draw_buf_init(&dsc->buf1, w, h, color_format, stride, dsc->mem, data_size);
169	    LV_LOG_USER("buf1 init done: %p", &dsc->buf1);
170	
171	    /* double buffer mode */
172	
173	    bool double_buffer = dsc->pinfo.yres_virtual == (dsc->vinfo.yres * 2);
174	    if(double_buffer) {
175	        if((ret = fbdev_init_mem2(dsc)) < 0) {
176	            goto errout;
177	        }
178	
179	        lv_draw_buf_init(&dsc->buf2, w, h, color_format, stride, dsc->mem2, data_size);
180	    }
181	
182	    lv_display_set_draw_buffers(disp, &dsc->buf1, double_buffer ? &dsc->buf2 : NULL);
183	    lv_display_set_color_format(disp, color_format);
184	    lv_display_set_render_mode(disp, LV_DISPLAY_RENDER_MODE_DIRECT);
185	    lv_display_set_resolution(disp, dsc->vinfo.xres, dsc->vinfo.yres);
186	    lv_timer_set_cb(disp->refr_timer, display_refr_timer_cb);
187	
188	#if LV_DRAW_TRANSFORM_USE_MATRIX
189	    lv_display_set_matrix_rotation(disp, true);
190	#endif
191	
192	    LV_LOG_USER("Resolution is set to %dx%d at %" LV_PRId32 "dpi",
193	                dsc->vinfo.xres, dsc->vinfo.yres, lv_display_get_dpi(disp));
194	    return 0;
195	
196	errout:
197	    close(dsc->fd);
198	    dsc->fd = -1;
199	    return ret;
200	}
