206	static void display_refr_timer_cb(lv_timer_t * tmr)
207	{
208	    lv_display_t * disp = lv_timer_get_user_data(tmr);
209	    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);
210	    struct pollfd pfds[1];
211	
212	    lv_memzero(pfds, sizeof(pfds));
213	    pfds[0].fd = dsc->fd;
214	    pfds[0].events = POLLOUT;
215	
216	    /* Query free fb to draw */
217	
218	    if(poll(pfds, 1, 0) < 0) {
219	        return;
220	    }
221	
222	    if(pfds[0].revents & POLLOUT) {
223	        _lv_display_refr_timer(tmr);
224	    }
225	}
