227	static void flush_cb(lv_display_t * disp, const lv_area_t * area, uint8_t * color_p)
228	{
229	    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);
230	
231	    static int flush_count = 0;
232	    flush_count++;
233	
234	    /* Skip the non-last flush */
235	
236	    if(!lv_display_flush_is_last(disp)) {
237	        lv_display_flush_ready(disp);
238	        return;
239	    }
240	
241	    if(dsc->mem == NULL ||
242	       area->x2 < 0 || area->y2 < 0 ||
243	       area->x1 > (int32_t)dsc->vinfo.xres - 1 || area->y1 > (int32_t)dsc->vinfo.yres - 1) {
244	        LV_LOG_ERROR("FLUSH[%d]: INVALID area", flush_count);
245	        lv_display_flush_ready(disp);
246	        return;
247	    }
248	
249	    /* FORCE FULL SCREEN FLUSH - for debugging */
250	    uint32_t x1 = 0;
251	    uint32_t y1 = 0;
252	    uint32_t x2 = dsc->vinfo.xres - 1;
253	    uint32_t y2 = dsc->vinfo.yres - 1;
254	    uint32_t stride = dsc->pinfo.stride;
255	
256	    /* Calculate the dirty region start and size in memory */
257	    uintptr_t start = (uintptr_t)color_p;
258	    size_t dirty_size = dsc->vinfo.yres * stride;
259	
260	    if(flush_count <= 5) {
261	        LV_LOG_USER("=== FLUSH[%d] (FORCED FULL SCREEN) ===", flush_count);
262	        LV_LOG_USER("  area: (%d,%d) to (%d,%d)", x1, y1, x2, y2);
263	        LV_LOG_USER("  color_p: %p", color_p);
264	        LV_LOG_USER("  stride: %d", stride);
265	        LV_LOG_USER("  dirty_size: %d bytes", dirty_size);
266	    }
267	
268	    /* Clean dcache for the dirty region */
269	    #include <nuttx/cache.h>
270	    up_clean_dcache(start, start + dirty_size);
271	
272	    if(flush_count <= 5) {
273	        LV_LOG_USER("FLUSH[%d]: dcache cleaned", flush_count);
274	    }
275	
276	#if defined(CONFIG_FB_UPDATE)
277	    /*May be some direct update command is required*/
278	    int yoffset = disp->buf_act == disp->buf_1 ?
279	                  0 : dsc->mem2_yoffset;
280	
281	    /* Join the areas to update */
282	    lv_area_t dirty_area;
283	    lv_display_get_dirty_area(disp, &dirty_area);
284	
285	    struct fb_area_s fb_area;
286	    fb_area.x = dirty_area.x1;
287	    fb_area.y = dirty_area.y1 + yoffset;
288	    fb_area.w = lv_area_get_width(&dirty_area);
289	    fb_area.h = lv_area_get_height(&dirty_area);
290	    if(ioctl(dsc->fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&fb_area)) < 0) {
291	        LV_LOG_ERROR("ioctl(FBIO_UPDATE) failed: %d", errno);
292	    }
293	#endif
294	
295	    /* double framebuffer */
296	
297	    if(dsc->mem2 != NULL) {
298	        if(disp->buf_act == disp->buf_1) {
299	            dsc->pinfo.yoffset = 0;
300	        }
301	        else {
302	            dsc->pinfo.yoffset = dsc->mem2_yoffset;
303	        }
304	
305	        if(ioctl(dsc->fd, FBIOPAN_DISPLAY, (unsigned long)((uintptr_t) & (dsc->pinfo))) < 0) {
306	            LV_LOG_ERROR("ioctl(FBIOPAN_DISPLAY) failed: %d", errno);
307	        }
308	    }
309	    lv_display_flush_ready(disp);
310	}
