312	static lv_color_format_t fb_fmt_to_color_format(int fmt)
313	{
314	    switch(fmt) {
315	        case FB_FMT_RGB16_565:
316	            return LV_COLOR_FORMAT_RGB565;
317	        case FB_FMT_RGB24:
318	            return LV_COLOR_FORMAT_RGB888;
319	        case FB_FMT_RGB32:
320	            return LV_COLOR_FORMAT_XRGB8888;
321	        case FB_FMT_RGBA32:
322	            return LV_COLOR_FORMAT_ARGB8888;
323	        default:
324	            break;
325	    }
326	
327	    LV_LOG_ERROR("Unsupported color format: %d", fmt);
328	
329	    return LV_COLOR_FORMAT_UNKNOWN;
330	}
