332	static int fbdev_get_pinfo(int fd, FAR struct fb_planeinfo_s * pinfo)
333	{
334	    if(ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)pinfo)) < 0) {
335	        LV_LOG_ERROR("ERROR: ioctl(FBIOGET_PLANEINFO) failed: %d", errno);
336	        return -errno;
337	    }
338	
339	    LV_LOG_USER("PlaneInfo (plane %d):", pinfo->display);
340	    LV_LOG_USER("    mem: %p", pinfo->fbmem);
341	    LV_LOG_USER("    fblen: %zu", pinfo->fblen);
342	    LV_LOG_USER("   stride: %u", pinfo->stride);
343	    LV_LOG_USER("  display: %u", pinfo->display);
344	    LV_LOG_USER("      bpp: %u", pinfo->bpp);
345	
346	    return 0;
347	}
