349	static int fbdev_init_mem2(lv_nuttx_fb_t * dsc)
350	{
351	    struct fb_planeinfo_s pinfo;
352	    void * phy_mem1;
353	    void * phy_mem2;
354	
355	    int ret;
356	
357	    /* Get display[0] planeinfo */
358	    lv_memzero(&pinfo, sizeof(pinfo));
359	    pinfo.display = dsc->pinfo.display;
360	    if((ret = fbdev_get_pinfo(dsc->fd, &pinfo)) < 0) return ret;
361	    phy_mem1 = pinfo.fbmem;
362	
363	    /* Get display[1] planeinfo */
364	    lv_memzero(&pinfo, sizeof(pinfo));
365	    pinfo.display = dsc->pinfo.display + 1;
366	    if((ret = fbdev_get_pinfo(dsc->fd, &pinfo)) < 0) return ret;
367	    phy_mem2 = pinfo.fbmem;
368	
369	    lv_uintptr_t offset = (lv_uintptr_t)phy_mem2 - (lv_uintptr_t)phy_mem1;
370	    bool is_consecutive = offset == 0;
371	
372	    /* Check bpp */
373	
374	    if(pinfo.bpp != dsc->pinfo.bpp) {
375	        LV_LOG_WARN("mem2 is incorrect");
376	        return -EINVAL;
377	    }
378	
379	    /* Check the buffer address offset,
380	     * It needs to be divisible by pinfo.stride
381	     */
382	
383	    if((offset % dsc->pinfo.stride) != 0) {
384	        LV_LOG_WARN("It is detected that buf_offset(%" PRIuPTR ") "
385	                    "and stride(%d) are not divisible, please ensure "
386	                    "that the driver handles the address offset by itself.",
387	                    offset, dsc->pinfo.stride);
388	    }
389	
390	    /* Calculate the address and yoffset of mem2 */
391	
392	    if(is_consecutive) {
393	        dsc->mem2_yoffset = dsc->vinfo.yres;
394	        offset = dsc->vinfo.yres * pinfo.stride;
395	    }
396	    else {
397	        dsc->mem2_yoffset = offset / dsc->pinfo.stride;
398	    }
399	
400	    uint32_t fblen = is_consecutive ? pinfo.fblen / 2 : pinfo.fblen;
401	    void * mem2 = mmap(NULL, fblen, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_FILE, dsc->fd, offset);
402	    if(mem2 == MAP_FAILED) {
403	        LV_LOG_ERROR("ERROR: mmap failed: %d, offset: %" PRIuPTR, errno, offset);
404	        return -errno;
405	    }
406	    dsc->mem2 = mem2;
407	
408	    LV_LOG_USER("Use of %sconsecutive mem2 = %p, yoffset = %" LV_PRIu32, is_consecutive ? "" : "non-", dsc->mem2,
409	                dsc->mem2_yoffset);
410	
411	    return 0;
412	}
413	
414	static void display_release_cb(lv_event_t * e)
415	{
416	    lv_display_t * disp = (lv_display_t *) lv_event_get_user_data(e);
417	    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);
418	    if(dsc) {
419	        lv_display_set_driver_data(disp, NULL);
420	        lv_display_set_flush_cb(disp, NULL);
421	
422	        if(dsc->mem != NULL && dsc->mem != MAP_FAILED) {
423	            /* Unmap the framebuffer memory */
424	            munmap(dsc->mem, dsc->pinfo.fblen);
425	            dsc->mem = NULL;
426	        }
427	
428	        if(dsc->mem2 != NULL && dsc->mem2 != MAP_FAILED) {
429	            /* Unmap the second framebuffer memory if double buffering is used */
430	            munmap(dsc->mem2, dsc->pinfo.fblen);
431	            dsc->mem2 = NULL;
432	        }
433	
