254	static uint32_t millis(void)
255	{
256	    struct timespec ts;
257	
258	    clock_gettime(CLOCK_MONOTONIC, &ts);
259	    uint32_t tick = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
260	
261	    return tick;
262	}
