266	{
267	    static const int priority[_LV_LOG_LEVEL_NUM] = {
268	        LOG_DEBUG, LOG_INFO, LOG_WARNING, LOG_ERR, LOG_CRIT
269	    };
270	
271	    syslog(priority[level], "[LVGL] %s", buf);
272	}
273	#endif
274	
275	static void check_stack_size(void)
276	{
277	    pthread_t tid = pthread_self();
278	    ssize_t stack_size = pthread_get_stacksize_np(tid);
279	    LV_LOG_USER("tid: %d, Stack size : %zd", (int)tid, stack_size);
280	
281	    if(stack_size < LV_NUTTX_MIN_STACK_SIZE) {
282	        LV_LOG_ERROR("Stack size is too small. Please increase it to %d bytes or more.",
283	                     LV_NUTTX_MIN_STACK_SIZE);
284	    }
285	}
