210	int sunxifb_updatearea(struct fb_vtable_s *vtable, FAR const struct fb_area_s *area)
211	{
212		hal_dcache_clean_invalidate((unsigned long)g_planeinfo.fbmem, g_planeinfo.fblen);
213	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
214		unsigned int *addr = (unsigned int *)0x05103010;
215		struct disp_layer_config config;
216		config.channel = 1;
217		config.layer_id = 0;
218		struct disp_manager *mgr =  g_disp_drv.mgr[0];
219		if (mgr && mgr->get_layer_config)
220			mgr->get_layer_config(mgr, &config, 1);
221		int y_offset = (*addr -  (unsigned int)fb_rot->dst_vir_addr) / fb_rot->pinfo->stride;
222		y_offset = (y_offset + g_videoinfo.yres) % (g_planeinfo.yres_virtual << 1);
223		if (fb_rot) {
224			fb_rot->pinfo->yoffset= y_offset;
225			fb_rot->apply(fb_rot);
226		}
227		config.info.fb.addr[0] = (unsigned long long)(unsigned int)(fb_rot->dst_phy_addr + fb_rot->pinfo->stride * y_offset);
228		if (mgr && mgr->set_layer_config)
229		mgr->set_layer_config(mgr, &config, 1);
230	#endif
231		return 0;
232	}
233	#endif
