332	/****************************************************************************
333	 * Name: up_fbinitialize
334	 *
335	 * Description:
336	 *   Initialize the framebuffer video hardware associated with the display.
337	 *
338	 * Input Parameters:
339	 *   display - In the case of hardware with multiple displays, this
340	 *     specifies the display.  Normally this is zero.
341	 *
342	 * Returned Value:
343	 *   Zero is returned on success; a negated errno value is returned on any
344	 *   failure.
345	 *
346	 ****************************************************************************/
347	
348	
349	int up_fbinitialize(int display)
350	{
351		int ret = -1;
352		// 获取旋转角度
353		s32 rotation_degree = 0;
354		disp_sys_script_get_item("disp", "degree0", &rotation_degree, 1);
355		disp_probe();
356		if ((g_disp_drv.disp_init.fb_width[display] == 0)
357			|| (g_disp_drv.disp_init.fb_height[display] == 0)) {
358	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
359			g_videoinfo.xres =
360				bsp_disp_get_screen_height_from_output_type
361				(display,
362				g_disp_drv.disp_init.output_type[display],
363				g_disp_drv.disp_init.output_mode[display]);
364			g_videoinfo.yres =
365				bsp_disp_get_screen_width_from_output_type
366				(display,
367				g_disp_drv.disp_init.output_type[display],
368				g_disp_drv.disp_init.output_mode[display]);
369	
370	#else
371			g_videoinfo.xres =
372				bsp_disp_get_screen_width_from_output_type
373				(display,
374				g_disp_drv.disp_init.output_type[display],
375				g_disp_drv.disp_init.output_mode[display]);
376			g_videoinfo.yres =
377				bsp_disp_get_screen_height_from_output_type
378				(display,
379				g_disp_drv.disp_init.output_type[display],
380				g_disp_drv.disp_init.output_mode[display]);
381	#endif
382		} else {
383	// 只有90/270度才交换宽高
384	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
385		if (rotation_degree == 1 || rotation_degree == 3) { // 90或270度
386			g_videoinfo.xres = g_disp_drv.disp_init.fb_height[display];
387			g_videoinfo.yres = g_disp_drv.disp_init.fb_width[display];
388		} else { // 0或180度不交换
389			g_videoinfo.xres = g_disp_drv.disp_init.fb_width[display];
390			g_videoinfo.yres = g_disp_drv.disp_init.fb_height[display];
391		}
392	#else
393			g_videoinfo.xres = g_disp_drv.disp_init.fb_width[display];
394			g_videoinfo.yres = g_disp_drv.disp_init.fb_height[display];
395	#endif
396		}
397		g_videoinfo.fmt = FB_FMT_RGB32;
398		g_videoinfo.nplanes = 1;
399	#ifdef CONFIG_FB_OVERLAY
400		g_videoinfo.noverlays = 1;
401	#endif
402		g_planeinfo.bpp = 32;
403		g_planeinfo.display = 0;
404		/* Force stride 64-byte alignment for Allwinner DE2.0 DMA */
405		g_planeinfo.stride = (g_videoinfo.xres * g_planeinfo.bpp / 8 + 63) & ~63;
406		g_planeinfo.fblen = g_planeinfo.stride * g_videoinfo.yres * FB_NUM;
407	
408		/* Ensure 64-byte alignment for LVGL */
409		uintptr_t map_vaddr = (uintptr_t)R528_DISP_DDR_MAPVADDR;
410		if (map_vaddr % 64 != 0)
411		{
412			lcdwarn("Warning: R528_DISP_DDR_MAPVADDR not 64-byte aligned: 0x%lx\\n", map_vaddr);
413			map_vaddr = (map_vaddr + 63) & ~63;
414		}
415		g_planeinfo.fbmem = (void *)map_vaddr;
416	
417		DEBUGASSERT(g_planeinfo.fbmem != NULL);
418		g_planeinfo.xres_virtual = g_videoinfo.xres;
419		g_planeinfo.yres_virtual = g_videoinfo.yres * FB_NUM;
420		g_planeinfo.display = display;
421		memset(g_planeinfo.fbmem, 0, g_planeinfo.fblen);
422	
423		struct disp_layer_config config;
424		memset(&config, 0, sizeof(struct disp_layer_config));
425		config.channel = 1;
426		config.layer_id = 0;
427		config.enable = 1;
428	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
429	if (rotation_degree == 1 || rotation_degree == 3) { // 90或270度才交换
430	    config.info.screen_win.width = g_videoinfo.yres;   // 600
431	    config.info.screen_win.height = g_videoinfo.xres;  // 1024
432	} else { // 0或180度不交换
433	    config.info.screen_win.width = g_videoinfo.xres;   // 1024
434	    config.info.screen_win.height = g_videoinfo.yres;  // 600
435	}
436	#else
437	    config.info.screen_win.width = g_videoinfo.xres;   // 1024
438	    config.info.screen_win.height = g_videoinfo.yres;  // 600
439	#endif
440		config.info.mode = LAYER_MODE_BUFFER;
441		config.info.zorder = 1;
442		config.info.alpha_mode = 0;
443		config.info.alpha_value = 0xff;
444		config.info.fb.crop.x = (0LL) << 32;
445		config.info.fb.crop.y = ((long long)g_planeinfo.yoffset) << 32;
446		config.info.fb.crop.width =
447		    ((long long)g_videoinfo.xres) << 32;
448		config.info.fb.crop.height =
449		    ((long long)g_videoinfo.yres) << 32;
450		config.info.screen_win.x = 0;
451		config.info.screen_win.y = 0;
452	
453		config.info.fb.addr[0] =
454		    (unsigned long long)(unsigned int)g_planeinfo.fbmem;
455		config.info.fb.addr[1] = 0;
456		config.info.fb.addr[2] = 0;
457		config.info.fb.flags = DISP_BF_NORMAL;
458		config.info.fb.scan = DISP_SCAN_PROGRESSIVE;
459		/* Tell DE engine the real memory stride (1088 pixels = 4352 bytes) */
460		config.info.fb.size[0].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
461		config.info.fb.size[0].height = g_planeinfo.yres_virtual;
462		config.info.fb.size[1].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
463		config.info.fb.size[1].height = g_planeinfo.yres_virtual;
464		config.info.fb.size[2].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
465		config.info.fb.size[2].height = g_planeinfo.yres_virtual;
466		config.info.fb.color_space = DISP_BT601;
467	
468		/* DEBUG: Print full layer config */
469		syslog(LOG_INFO, "=== DE2.0 LAYER CONFIG ===");
470		syslog(LOG_INFO, "  xres = %d", g_videoinfo.xres);
471		syslog(LOG_INFO, "  yres = %d", g_videoinfo.yres);
472		syslog(LOG_INFO, "  bpp = %d", g_planeinfo.bpp);
473		syslog(LOG_INFO, "  stride (bytes) = %d", g_planeinfo.stride);
474		syslog(LOG_INFO, "  stride (pixels) = %d", config.info.fb.size[0].width);
475		syslog(LOG_INFO, "  fb.addr[0] = 0x%llx", config.info.fb.addr[0]);
476		syslog(LOG_INFO, "  fb.size[0].width = %d", config.info.fb.size[0].width);
477		syslog(LOG_INFO, "  fb.size[0].height = %d", config.info.fb.size[0].height);
478		syslog(LOG_INFO, "  fb.crop.width = %lld", config.info.fb.crop.width);
479		syslog(LOG_INFO, "  fb.crop.height = %lld", config.info.fb.crop.height);
480		syslog(LOG_INFO, "  screen_win.width = %d", config.info.screen_win.width);
481		syslog(LOG_INFO, "  screen_win.height = %d", config.info.screen_win.height);
482	
483		hal_dcache_clean_invalidate((unsigned long)g_planeinfo.fbmem, g_planeinfo.fblen);
484	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
485		fb_rot = fb_g2d_rot_create(&g_videoinfo, &g_planeinfo, 0, &config);
486	#ifdef CONFIG_DISP_BOOTLOADER_SYNC
487		unsigned int *addr = (unsigned int *)0x05103010;
488		config.info.fb.addr[0] = (unsigned long long)(*addr);
489	#endif
490		if (fb_rot)
491			fb_rot->apply(fb_rot);
492	#endif
493		struct disp_manager *mgr =  g_disp_drv.mgr[display];
494		if (mgr && mgr->set_layer_config)
495			ret = mgr->set_layer_config(mgr, &config, 1);
496	#ifdef CONFIG_FB_OVERLAY
497		layer_lock = hal_mutex_create();
498		syslog(LOG_DEBUG, "up_fbinitialize:%d", VIDEO_WIDTH * VIDEO_HEIGHT * 3 / 2 * FB_NUM_OVERLAY);
499		syslog(LOG_DEBUG, "VIDEO_WIDTH:%d", VIDEO_WIDTH);
500		syslog(LOG_DEBUG, "VIDEO_HEIGHT:%d", VIDEO_HEIGHT);
501		syslog(LOG_DEBUG, "FB_NUM_OVERLAY:%d", FB_NUM_OVERLAY);
502		g_overlayinfo.fbmem = hal_malloc_align(VIDEO_WIDTH * VIDEO_HEIGHT * 3 / 2 * FB_NUM_OVERLAY, 4 * 1024);
503		memset(g_overlayinfo.fbmem, 0, VIDEO_WIDTH * VIDEO_HEIGHT * 3 / 2 * FB_NUM_OVERLAY);
504		g_overlayinfo.fblen = VIDEO_WIDTH * VIDEO_HEIGHT * 3 / 2 * FB_NUM_OVERLAY;
505		g_overlayinfo.stride = VIDEO_WIDTH;
506		g_overlayinfo.overlay = 0;
507		g_overlayinfo.bpp = 8;
508		g_overlayinfo.blank = 0;
509		g_overlayinfo.chromakey = 0;
510		g_overlayinfo.color = FB_FMT_NV21;
511		g_overlayinfo.transp.transp_mode = FB_CONST_ALPHA;
512		g_overlayinfo.transp.transp = 0xff;
513		g_overlayinfo.sarea.x = 0;
514		g_overlayinfo.sarea.y = 0;
515		g_overlayinfo.sarea.w = VIDEO_WIDTH;
516		g_overlayinfo.sarea.h = VIDEO_HEIGHT;
517		g_overlayinfo.xoffset = 0;
518		g_overlayinfo.yoffset = 0;
519		g_overlayinfo.xres = VIDEO_WIDTH;
520		g_overlayinfo.yres = VIDEO_HEIGHT;
521		g_overlayinfo.xres_virtual=VIDEO_WIDTH;
522		g_overlayinfo.yres_virtual=VIDEO_HEIGHT * FB_NUM_OVERLAY;
523		g_overlayinfo.darea.x = 0;
524		g_overlayinfo.darea.y = 0;
525		g_overlayinfo.darea.w = g_videoinfo.xres;
526		g_overlayinfo.darea.h = g_videoinfo.yres;
527		g_overlayinfo.accl = (FB_ACCL_TRANSP | FB_ACCL_AREA);
528	#endif
529		return ret;
530	}
