1	/****************************************************************************
2	 * apps/examples/screentest/screentest.c
3	 *
4	 * Simple screen test for 6FHD display (1080x1920)
5	 * Displays color blocks to verify all screen areas are working
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <unistd.h>
10	#include <stdio.h>
11	#include <lvgl/lvgl.h>
12	
13	/* Screen resolution - matches our 6FHD panel */
14	#define SCREEN_WIDTH  1080
15	#define SCREEN_HEIGHT 2160
16	
17	/* Color definitions */
18	#define COLOR_RED     0xFF0000
19	#define COLOR_GREEN   0x00FF00
20	#define COLOR_BLUE    0x0000FF
21	#define COLOR_WHITE   0xFFFFFF
22	#define COLOR_BLACK   0x000000
23	#define COLOR_YELLOW  0xFFFF00
24	#define COLOR_CYAN    0x00FFFF
25	#define COLOR_MAGENTA 0xFF00FF
26	
27	/* Grid: 3 columns x 4 rows */
28	#define GRID_COLS 3
29	#define GRID_ROWS 4
30	#define CELL_W (SCREEN_WIDTH / GRID_COLS)
31	#define CELL_H (SCREEN_HEIGHT / GRID_ROWS)
32	
33	static const lv_color_t grid_colors[GRID_ROWS][GRID_COLS] = {
34	    {LV_COLOR_MAKE(0xFF, 0x00, 0x00), LV_COLOR_MAKE(0x00, 0xFF, 0x00), LV_COLOR_MAKE(0x00, 0x00, 0xFF)},
35	    {LV_COLOR_MAKE(0xFF, 0xFF, 0x00), LV_COLOR_MAKE(0x00, 0xFF, 0xFF), LV_COLOR_MAKE(0xFF, 0x00, 0xFF)},
36	    {LV_COLOR_MAKE(0xFF, 0xFF, 0xFF), LV_COLOR_MAKE(0x80, 0x80, 0x80), LV_COLOR_MAKE(0x00, 0x00, 0x00)},
37	    {LV_COLOR_MAKE(0xFF, 0x80, 0x00), LV_COLOR_MAKE(0x80, 0x00, 0xFF), LV_COLOR_MAKE(0x00, 0x80, 0x80)},
38	};
39	
40	static void draw_test_pattern(void)
41	{
42	    lv_obj_t *scr = lv_scr_act();
43	    lv_obj_set_style_bg_color(scr, lv_color_hex(0x000000), 0);
44	
45	    /* Draw grid of color blocks */
46	    for (int row = 0; row < GRID_ROWS; row++) {
47	        for (int col = 0; col < GRID_COLS; col++) {
48	            lv_obj_t *rect = lv_obj_create(scr);
49	            lv_obj_set_size(rect, CELL_W - 2, CELL_H - 2);
50	            lv_obj_set_pos(rect, col * CELL_W + 1, row * CELL_H + 1);
51	            lv_obj_set_style_bg_color(rect, grid_colors[row][col], 0);
52	            lv_obj_set_style_border_width(rect, 0, 0);
53	            lv_obj_set_style_radius(rect, 0, 0);
54	            lv_obj_clear_flag(rect, LV_OBJ_FLAG_SCROLLABLE);
55	
56	            /* Add label with coordinates */
57	            lv_obj_t *label = lv_label_create(rect);
58	            lv_label_set_text_fmt(label, "%d,%d\n(%dx%d)", 
59	                col, row, CELL_W, CELL_H);
60	            lv_obj_set_style_text_color(label, 
61	                (row == 2 && col == 2) ? lv_color_hex(0xFFFFFF) : lv_color_hex(0x000000), 0);
62	            lv_obj_set_style_text_font(label, &lv_font_montserrat_16, 0);
63	            lv_obj_center(label);
64	        }
65	    }
66	
67	    /* Title */
68	    lv_obj_t *title = lv_label_create(scr);
69	    lv_label_set_text_fmt(title, "6FHD Screen Test: %dx%d", SCREEN_WIDTH, SCREEN_HEIGHT);
70	    lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
71	    lv_obj_set_style_text_font(title, &lv_font_montserrat_48, 0);
72	    lv_obj_align(title, LV_ALIGN_CENTER, 0, -20);
73	
74	    /* Info */
75	    lv_obj_t *info = lv_label_create(scr);
76	    lv_label_set_text(info, "Check all color blocks are visible\n"
77	                            "Center should show coordinates\n"
78	                            "Press any key to exit");
79	    lv_obj_set_style_text_color(info, lv_color_hex(0xFFFF00), 0);
80	    lv_obj_set_style_text_font(info, &lv_font_montserrat_16, 0);
81	    lv_obj_align(info, LV_ALIGN_CENTER, 0, 30);
82	}
83	
84	int main(int argc, FAR char *argv[])
85	{
86	    lv_init();
87	
88	    /* Initialize NuttX display driver */
89	    lv_nuttx_dsc_t info;
90	    lv_nuttx_result_t result;
91	    
92	    lv_nuttx_dsc_init(&info);
93	#ifdef CONFIG_LV_USE_NUTTX_LCD
94	    info.fb_path = "/dev/lcd0";
95	#endif
96	#ifdef CONFIG_INPUT_TOUCHSCREEN
97	    info.input_path = "/dev/input0";
98	#endif
99	    
100	    lv_nuttx_init(&info, &result);
101	    
102	    if (result.disp == NULL) {
103	        printf("ERROR: Failed to initialize display\n");
104	        return 1;
105	    }
106	
107	    printf("Display initialized: %dx%d\n", 
108	        (int)lv_disp_get_hor_res(result.disp),
109	        (int)lv_disp_get_ver_res(result.disp));
110	
111	    draw_test_pattern();
112	
113	    /* Main loop */
114	    while (1) {
115	        uint32_t idle = lv_timer_handler();
116	        idle = idle ? idle : 1;
117	        usleep(idle * 1000);
118	    }
119	
120	    return 0;
121	}
